from pathlib import Path

path = Path('/app/experimental_children_v1.py')
text = path.read_text(encoding='utf-8')

# Add baked Mega53 constants beside the specialist model constants.
needle = 'SAX_MODEL = "filosax_demucs_v3_14.22_SDR.th"\n'
replacement = needle + 'MEGA53_CONFIG = Path("/models/mss_training/mvsep-mega53/config.yaml")\nMEGA53_CHECKPOINT = Path("/models/mss_training/mvsep-mega53/model.ckpt")\nDEMUCS3_PYTHON = Path("/opt/demucs3/bin/python")\n'
if needle not in text:
    raise RuntimeError('Could not locate specialist constants')
text = text.replace(needle, replacement, 1)

# Require the router model and compatible Demucs v3 runtime.
old_required = 'required = [DRUM5_CONFIG, DRUM5_CHECKPOINT, SAX_MODEL_DIR / SAX_MODEL, audio_separator_model_dir / WIND_MODEL]'
new_required = 'required = [DRUM5_CONFIG, DRUM5_CHECKPOINT, SAX_MODEL_DIR / SAX_MODEL, audio_separator_model_dir / WIND_MODEL, MEGA53_CONFIG, MEGA53_CHECKPOINT, DEMUCS3_PYTHON]'
if old_required not in text:
    raise RuntimeError('Could not locate required-model list')
text = text.replace(old_required, new_required, 1)

# Add a Mega53 work directory.
text = text.replace('wind_out = root / "wind"\n        sax_out = root / "sax"', 'wind_out = root / "wind"\n        mega_out = root / "mega53"\n        mega_in = root / "mega53_in"\n        sax_out = root / "sax"', 1)
text = text.replace('for d in (srcdir, swout, drum_in, drum_out, wind_out, sax_out, final, experimental, logs):', 'for d in (srcdir, swout, drum_in, drum_out, wind_out, mega_out, mega_in, sax_out, final, experimental, logs):', 1)

# Apply one common peak-safe gain to all drum children. This preserves their
# relative balance/sum while preventing export clipping at full scale.
old_drum = '''                for name in DRUM5:\n                    dest = experimental / f"{track}_drums_5stem_{name}.flac"\n                    _write_flac(dest, loaded[name][:dn], drum_sr)\n                    drum_report["files"].append(dest.name)\n'''
new_drum = '''                target_peak = float(10.0 ** (-1.0 / 20.0))\n                raw_peak = max(float(np.max(np.abs(loaded[name][:dn]))) for name in DRUM5)\n                export_gain = min(1.0, target_peak / max(raw_peak, 1e-12))\n                drum_report["raw_max_peak"] = round(raw_peak, 6)\n                drum_report["export_headroom_db"] = -1.0\n                drum_report["common_export_gain"] = round(export_gain, 8)\n                for name in DRUM5:\n                    dest = experimental / f"{track}_drums_5stem_{name}.flac"\n                    _write_flac(dest, loaded[name][:dn] * export_gain, drum_sr)\n                    drum_report["files"].append(dest.name)\n'''
if old_drum not in text:
    raise RuntimeError('Could not locate drum export loop')
text = text.replace(old_drum, new_drum, 1)

old_family = '''        emit("Running Wind Family Separation", 56)\n        other_parent = root / "other_parent.flac"\n        _copy_as_flac(stems["other"], other_parent)\n        t0 = time.monotonic()\n        wind_cmd = ["audio-separator", str(other_parent), "--model_filename", WIND_MODEL, "--model_file_dir", str(audio_separator_model_dir), "--output_dir", str(wind_out), "--output_format", "FLAC"]\n        wind = subprocess.run(wind_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=timeout)\n        timings["wind_uvr"] = round(time.monotonic() - t0, 3)\n\n        wind_files: list[str] = []\n        woodwind_path = None\n        wind_residual_path = None\n        if wind.returncode == 0:\n            candidates = [p for p in wind_out.rglob("*") if p.is_file() and p.suffix.lower() in {".wav", ".flac", ".mp3"}]\n            woodwind_src = next((p for p in candidates if "woodwind" in p.name.lower() and "no_woodwind" not in p.name.lower() and "no woodwind" not in p.name.lower() and "no-woodwind" not in p.name.lower()), None)\n            residual_src = next((p for p in candidates if "no_woodwind" in p.name.lower() or "no woodwind" in p.name.lower() or "no-woodwind" in p.name.lower()), None)\n            if woodwind_src:\n                woodwind_path = experimental / f"{track}_wind_woodwinds.flac"\n                _copy_as_flac(woodwind_src, woodwind_path)\n                wind_files.append(woodwind_path.name)\n            if residual_src:\n                wind_residual_path = experimental / f"{track}_wind_residual.flac"\n                _copy_as_flac(residual_src, wind_residual_path)\n                wind_files.append(wind_residual_path.name)\n            if not woodwind_src and not residual_src:\n                wind_files = _copy_audio_tree(wind_out, experimental, f"{track}_wind_uvr")\n\n        emit("Running Saxophone Specialist Separation", 74)\n        t0 = time.monotonic()\n        sax_input = woodwind_path if woodwind_path and woodwind_path.is_file() else other_parent\n        sax_cmd = ["python", "-m", "demucs", "--repo", str(SAX_MODEL_DIR), "-n", SAX_MODEL, "-o", str(sax_out), str(sax_input)]\n        sax = subprocess.run(sax_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=timeout)\n        timings["sax_demucs"] = round(time.monotonic() - t0, 3)\n        sax_files = _copy_audio_tree(sax_out, experimental, f"{track}_sax_specialist") if sax.returncode == 0 else []\n'''
new_family = '''        # Mega53 is the routing brain: identify whether the Other parent is\n        # woodwind-led, brass-led, mixed, or has no convincing wind family.\n        other_parent = root / "other_parent.flac"\n        _copy_as_flac(stems["other"], other_parent)\n        _copy_as_flac(stems["other"], mega_in / "other.flac")\n        emit("Running Mega53 Instrument Inventory", 54)\n        rc, elapsed = _run_polled(\n            ["python", str(repo_dir / "inference.py"), "--model_type", "bs_roformer", "--config_path", str(MEGA53_CONFIG), "--start_check_point", str(MEGA53_CHECKPOINT), "--input_folder", str(mega_in), "--store_dir", str(mega_out), "--device_ids", "0", "--disable_detailed_pbar", "--filename_template", "{file_name}/{instr}"],\n            cwd=repo_dir, timeout=timeout, log_path=logs / "mega53.log", progress=None,\n            stage_name="Mega53 instrument inventory", start_percent=54, end_percent=68, heartbeat_seconds=heartbeat,\n        )\n        timings["mega53"] = round(elapsed, 3)\n        inventory = {}\n        if rc == 0:\n            mega_files = [p for p in mega_out.rglob("*") if p.is_file() and p.suffix.lower() in {".wav", ".flac"}]\n            mega_by_name = {p.stem.lower().replace("_", "-"): p for p in mega_files}\n            parent_audio, _ = _read(other_parent)\n            for name in ("saxophone", "trumpet", "brass", "wind", "woodwind", "trombone", "french-horn", "clarinet", "flute", "oboe"):\n                p = mega_by_name.get(name)\n                if not p:\n                    continue\n                a, _ = _read(p)\n                n2 = min(len(a), len(parent_audio))\n                rms = float(np.sqrt(np.mean(a[:n2] * a[:n2]) + 1e-12))\n                inventory[name] = {"rms_dbfs": _db(rms), "parent_cosine": round(float(_cos(a[:n2], parent_audio[:n2])), 6)}\n\n        def inv_score(name: str) -> bool:\n            item = inventory.get(name) or {}\n            return float(item.get("rms_dbfs", -99.0)) >= -42.0 and abs(float(item.get("parent_cosine", 0.0))) >= 0.20\n\n        brass_detected = any(inv_score(x) for x in ("trumpet", "brass", "trombone", "french-horn"))\n        woodwind_detected = any(inv_score(x) for x in ("saxophone", "wind", "woodwind", "clarinet", "flute", "oboe"))\n        sax_detected = inv_score("saxophone")\n        family_route = "mixed_wind_brass" if brass_detected and woodwind_detected else ("brass" if brass_detected else ("woodwind" if woodwind_detected else "none"))\n\n        wind_files: list[str] = []\n        woodwind_path = None\n        family_path = None\n        wind_residual_path = None\n        wind_returncode = None\n        wind_stdout = ""\n        if family_route != "none":\n            emit("Running Wind/Brass Family Separation", 70)\n            t0 = time.monotonic()\n            wind_cmd = ["audio-separator", str(other_parent), "--model_filename", WIND_MODEL, "--model_file_dir", str(audio_separator_model_dir), "--output_dir", str(wind_out), "--output_format", "FLAC"]\n            wind = subprocess.run(wind_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=timeout)\n            wind_returncode = wind.returncode\n            wind_stdout = wind.stdout or ""\n            timings["wind_uvr"] = round(time.monotonic() - t0, 3)\n            if wind.returncode == 0:\n                candidates = [p for p in wind_out.rglob("*") if p.is_file() and p.suffix.lower() in {".wav", ".flac", ".mp3"}]\n                target_src = next((p for p in candidates if "woodwind" in p.name.lower() and "no_woodwind" not in p.name.lower() and "no woodwind" not in p.name.lower() and "no-woodwind" not in p.name.lower()), None)\n                residual_src = next((p for p in candidates if "no_woodwind" in p.name.lower() or "no woodwind" in p.name.lower() or "no-woodwind" in p.name.lower()), None)\n                if target_src:\n                    family_slug = "woodwinds" if family_route == "woodwind" else ("brass_family" if family_route == "brass" else "wind_brass_family")\n                    family_path = experimental / f"{track}_{family_slug}.flac"\n                    _copy_as_flac(target_src, family_path)\n                    wind_files.append(family_path.name)\n                    if family_route in {"woodwind", "mixed_wind_brass"}:\n                        woodwind_path = family_path\n                if residual_src:\n                    wind_residual_path = experimental / f"{track}_wind_brass_residual.flac"\n                    _copy_as_flac(residual_src, wind_residual_path)\n                    wind_files.append(wind_residual_path.name)\n\n        # The published sax model explicitly requires Demucs 3.0.6. Only run it\n        # when Mega53 actually sees saxophone, and feed the family child first.\n        sax_files: list[str] = []\n        sax_returncode = None\n        sax_stdout = ""\n        if sax_detected:\n            emit("Running Saxophone Specialist Separation", 82)\n            t0 = time.monotonic()\n            sax_input = woodwind_path if woodwind_path and woodwind_path.is_file() else (family_path if family_path and family_path.is_file() else other_parent)\n            sax_cmd = [str(DEMUCS3_PYTHON), "-m", "demucs", "--repo", str(SAX_MODEL_DIR), "-n", SAX_MODEL, "-o", str(sax_out), str(sax_input)]\n            sax = subprocess.run(sax_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, timeout=timeout)\n            sax_returncode = sax.returncode\n            sax_stdout = sax.stdout or ""\n            timings["sax_demucs"] = round(time.monotonic() - t0, 3)\n            sax_files = _copy_audio_tree(sax_out, experimental, f"{track}_sax_specialist") if sax.returncode == 0 else []\n'''
if old_family not in text:
    raise RuntimeError('Could not locate family-first wind/sax block; apply this patch after litelabs_family_first_patch.py')
text = text.replace(old_family, new_family, 1)

old_report = '''            "wind": {\n                "ok": wind.returncode == 0,\n                "architecture": "Other parent -> Woodwinds + Wind Residual",\n                "woodwinds_file": woodwind_path.name if woodwind_path else None,\n                "residual_file": wind_residual_path.name if wind_residual_path else None,\n                "files": wind_files,\n                "runtime_tail": "\\n".join((wind.stdout or "").splitlines()[-25:]) if wind.returncode else "",\n            },\n            "saxophone": {\n                "ok": sax.returncode == 0,\n                "input": "Woodwinds child" if woodwind_path else "Other parent fallback",\n                "files": sax_files,\n                "runtime_tail": "\\n".join((sax.stdout or "").splitlines()[-25:]) if sax.returncode else "",\n            },\n'''
new_report = '''            "mega53_inventory": {"ok": rc == 0, "route": family_route, "evidence": inventory},\n            "wind": {\n                "ok": wind_returncode == 0 if wind_returncode is not None else False,\n                "ran": family_route != "none",\n                "route": family_route,\n                "architecture": "Other parent -> routed Wind/Brass family + residual",\n                "family_file": family_path.name if family_path else None,\n                "residual_file": wind_residual_path.name if wind_residual_path else None,\n                "files": wind_files,\n                "runtime_tail": "\\n".join(wind_stdout.splitlines()[-25:]),\n            },\n            "saxophone": {\n                "ran": sax_detected,\n                "ok": sax_returncode == 0 if sax_returncode is not None else False,\n                "router_detected_sax": sax_detected,\n                "input": "routed family child" if family_path else "Other parent fallback",\n                "files": sax_files,\n                "runtime_tail": "\\n".join(sax_stdout.splitlines()[-25:]),\n            },\n'''
if old_report not in text:
    raise RuntimeError('Could not locate family report block')
text = text.replace(old_report, new_report, 1)

# Bump experimental report schema for routed inventory/headroom behaviour.
text = text.replace('"schema_version": 3,', '"schema_version": 4,', 1)
path.write_text(text, encoding='utf-8')
print('LiteLABS Mega53 quality router, drum headroom and Demucs v3 sax patch applied')
